constrained = positives + negatives
assert len(constrained) == len(set(constrained)) == 1624, "wrong number of constraints or a repeat"
assert all(65 <= v <= 3312 for v in constrained), "constraint on a non-wire variable"
assert not set(positives) & set(negatives), "a wire is required to be both 0 and 1"

import os
if os.path.exists("node_index.txt"):
    kinds = [l.split("(")[0].strip() for l in open("node_index.txt") if "(" in l]
    assert all(kinds[v - 1] == "WIRE" for v in constrained), "node_index mismatch"
    print("node_index.txt check passed")

additional_clauses = [[pos] for pos in positives] + [[-neg] for neg in negatives]
clauses.extend(additional_clauses)
print(f"Added {len(additional_clauses)} constraint clauses "
      f"({len(positives)} wires = 1, {len(negatives)} wires = 0). Total clauses: {len(clauses)}")
